<?php
require_once __DIR__ . '/inc/bootstrap.php';
require_once __DIR__ . '/inc/turnstile.php';
require_once __DIR__ . '/inc/public_contact.php';
header('Cache-Control: no-store');
$pdo = db();
tickex_public_contact_ensure_schema($pdo);
$error = ''; $success = ''; $reference = '';
$reason = isset($_POST['reason']) ? strtolower(trim((string)$_POST['reason'])) : (isset($_GET['motivo']) ? strtolower(trim((string)$_GET['motivo'])) : '');
if (!in_array($reason, array('empezar','inicial','crecimiento','profesional'), true)) $reason = '';
$values = array('name'=>'','email'=>'','phone'=>'','organization'=>'','event_type'=>'','message'=>'');
foreach ($values as $key=>$unused) if (isset($_POST[$key])) $values[$key] = trim((string)$_POST[$key]);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!tickex_csrf_verify(isset($_POST['_csrf']) ? (string)$_POST['_csrf'] : '')) $error = 'La sesión venció. Actualizá la página.';
    elseif (!empty($_POST['website'])) $error = 'No pudimos enviar la consulta.';
    elseif (!empty($_SESSION['_public_contact_at']) && time() - (int)$_SESSION['_public_contact_at'] < 45) $error = 'Esperá unos segundos antes de enviar otra consulta.';
    else {
        $captchaErrors = array(); tickex_turnstile_verify_post($captchaErrors);
        if ($captchaErrors) $error = $captchaErrors[0];
        else {
            list($ok,$message,$reference) = tickex_public_contact_create($pdo, $_POST);
            if ($ok) { $success = $message; $_SESSION['_public_contact_at'] = time(); }
            else $error = $message;
        }
    }
}
$csrf = tickex_csrf_token();
function contact_e($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
